    [Fact]
    public async Task GetHealthAsyncReturnsTextResponse()
    {
        using var handler = new RecordingHandler(_ => new HttpResponseMessage(HttpStatusCode.OK)
        {
            Content = new StringContent("ok"),
        });

        using var client = new ToriiClient(
            new Uri("https://torii.example"),
            new HttpClient(handler));
        var health = await client.GetHealthAsync(cancellationToken: TestContext.Current.CancellationToken);

        Assert.Equal("ok", health);
        Assert.Equal("/v1/health", handler.LastRequest!.RequestUri!.AbsolutePath);
    }

    [Fact]
    public async Task GetHealthAsyncRejectsInvalidUtf8TextResponse()
    {
        using var handler = new RecordingHandler(_ => new HttpResponseMessage(HttpStatusCode.OK)
        {
            Content = new ByteArrayContent([0xff, 0xfe, 0xfd]),
        });

        using var client = new ToriiClient(
            new Uri("https://torii.example"),
            new HttpClient(handler));

        var error = await Assert.ThrowsAsync<InvalidDataException>(() => client.GetHealthAsync(cancellationToken: TestContext.Current.CancellationToken));

        Assert.Contains("Torii health response body must be valid UTF-8", error.Message, StringComparison.Ordinal);
    }

    [Fact]
    public async Task GetMetricsAsyncReturnsTextResponse()
    {
        using var handler = new RecordingHandler(_ => new HttpResponseMessage(HttpStatusCode.OK)
