    [Fact]
    public async Task GetAsyncRejectsCaseDriftedRawSoraFsStorageClassResponse()
    {
        using var handler = new RecordingHandler(_ => new HttpResponseMessage(HttpStatusCode.OK)
        {
            Content = new StringContent("""{"Type":"Hot"}"""),
        });
        using var client = new ToriiClient(new Uri("https://torii.example"), new HttpClient(handler));

        var error = await Assert.ThrowsAsync<JsonException>(() =>
            client.GetAsync<ToriiSoraFsStorageClass>("/v1/raw", cancellationToken: TestContext.Current.CancellationToken));

        Assert.Contains("type", error.Message);
        Assert.Contains("non-empty string", error.Message);
        Assert.Equal("/v1/raw", handler.LastRequest!.RequestUri!.AbsolutePath);
    }

    [Theory]
    [InlineData("", "empty or whitespace")]
    [InlineData(" ", "empty or whitespace")]
    [InlineData(" dev-token", "surrounding whitespace")]
    [InlineData("dev-token ", "surrounding whitespace")]
    [InlineData("dev token", "whitespace")]
    [InlineData("dev\u00A0token", "whitespace")]
    [InlineData("dev-token\u0001", "control characters")]
    [InlineData("=", "HTTP bearer token")]
    [InlineData("dev=token", "trailing-only")]
    [InlineData("dev=token=", "trailing-only")]
    [InlineData("dev:token", "HTTP bearer token")]
    [InlineData("dev,token", "HTTP bearer token")]
    [InlineData("dev;token", "HTTP bearer token")]
    [InlineData("dev(token)", "HTTP bearer token")]
    [InlineData("dev[token]", "HTTP bearer token")]
    [InlineData("dev\\token", "HTTP bearer token")]
    [InlineData("dev\"token", "HTTP bearer token")]
    [InlineData("dev?token", "HTTP bearer token")]
    [InlineData("dev@token", "HTTP bearer token")]
    [InlineData("dev\u007Ftoken", "control characters")]
    [InlineData("devétoken", "HTTP bearer token")]
    public async Task SendAsyncRejectsNonExactBearerTokensBeforeDispatchAndCanonicalSigning(
        string bearerToken,
        string expectedMessage)
    {
        using var handler = new RecordingHandler(_ =>
            throw new InvalidOperationException("non-exact bearer token reached HTTP dispatch"));
        using var client = new ToriiClient(
            new Uri("https://torii.example"),
            new HttpClient(handler),
            new ToriiClientOptions
            {
                BearerToken = bearerToken,
                CanonicalRequestCredentials = new CanonicalRequestCredentials(
                    CanonicalAccountId,
                    CanonicalPrivateKeySeed),
            });

        var error = await Assert.ThrowsAsync<ArgumentException>(() =>
            client.GetJsonDocumentAsync("/v1/query", "gas_units=100", cancellationToken: TestContext.Current.CancellationToken));

        Assert.Equal("BearerToken", error.ParamName);
        Assert.Contains(expectedMessage, error.Message);
        Assert.Null(handler.LastRequest);
    }

    [Theory]
    [InlineData("dev-token")]
    [InlineData("eyJhbGciOiJFZERTQSJ9.payload_signature")]
    [InlineData("abc.DEF-ghi_jkl~mno+/==")]
    public async Task SendAsyncAcceptsBearerTokenGrammarBeforeCanonicalSigning(string bearerToken)
    {
        using var handler = new RecordingHandler(_ => new HttpResponseMessage(HttpStatusCode.OK)
        {
            Content = new StringContent("{\"ok\":true}"),
        });
        using var client = new ToriiClient(
            new Uri("https://torii.example"),
            new HttpClient(handler),
            new ToriiClientOptions
            {
                BearerToken = bearerToken,
                CanonicalRequestCredentials = new CanonicalRequestCredentials(
                    CanonicalAccountId,
                    CanonicalPrivateKeySeed),
            });

        using var document = await client.GetJsonDocumentAsync("/v1/query", "gas_units=100", cancellationToken: TestContext.Current.CancellationToken);

        Assert.True(document.RootElement.GetProperty("ok").GetBoolean());
        Assert.Equal("Bearer", handler.LastRequest!.Headers.Authorization?.Scheme);
        Assert.Equal(bearerToken, handler.LastRequest.Headers.Authorization?.Parameter);
        Assert.True(handler.LastRequest.Headers.Contains("X-Iroha-Signature"));
    }

