    [InlineData("/json")]
    [InlineData("* / *")]
    [InlineData("*/json")]
    [InlineData("application/json;q=0.8")]
    [InlineData("application/json; q=0.8")]
    [InlineData("application/json, text/plain")]
    [InlineData("application/json;bad")]
