    [InlineData("application/тест")]
    public async Task SendAsyncRejectsNonExactAcceptHeadersBeforeDispatchAndCanonicalSigning(string accept)
    {
        using var handler = new RecordingHandler(_ =>
            throw new InvalidOperationException("non-exact Torii accept header reached HTTP dispatch"));
        using var client = new ToriiClient(
            new Uri("https://torii.example"),
            new HttpClient(handler),
            new ToriiClientOptions
            {
                CanonicalRequestCredentials = new CanonicalRequestCredentials(
                    CanonicalAccountId,
                    CanonicalPrivateKeySeed),
            });

        var error = await Assert.ThrowsAsync<ArgumentException>(() =>
            client.SendAsync(HttpMethod.Get, "/v1/query", accept: accept, cancellationToken: TestContext.Current.CancellationToken));

        Assert.Equal("accept", error.ParamName);
        Assert.Null(handler.LastRequest);
    }

    [Theory]
    [InlineData("application/json")]
    [InlineData("application/vnd.iroha+json")]
    [InlineData("application/*")]
    [InlineData("*/*")]
    public async Task SendAsyncAcceptsSingleMediaRangeAcceptHeadersBeforeCanonicalSigning(string accept)
    {
        using var handler = new RecordingHandler(_ => new HttpResponseMessage(HttpStatusCode.OK)
        {
            Content = new StringContent("{\"ok\":true}"),
        });
        using var client = new ToriiClient(
            new Uri("https://torii.example"),
            new HttpClient(handler),
            new ToriiClientOptions
            {
                CanonicalRequestCredentials = new CanonicalRequestCredentials(
                    CanonicalAccountId,
                    CanonicalPrivateKeySeed),
            });

        using var response = await client.SendAsync(HttpMethod.Get, "/v1/query", accept: accept, cancellationToken: TestContext.Current.CancellationToken);

        Assert.Contains(handler.LastRequest!.Headers.Accept, value => value.MediaType == accept);
        Assert.True(handler.LastRequest.Headers.Contains("X-Iroha-Signature"));
    }

    [Fact]
    public async Task SendAsyncAllowsConfigureRequestToAddNonReservedHeadersBeforeDispatch()
    {
        using var handler = new RecordingHandler(_ => new HttpResponseMessage(HttpStatusCode.OK)
        {
            Content = new StringContent("{\"ok\":true}"),
        });
        using var client = new ToriiClient(
            new Uri("https://torii.example"),
            new HttpClient(handler),
            new ToriiClientOptions
            {
                BearerToken = "dev-token",
                CanonicalRequestCredentials = new CanonicalRequestCredentials(
                    CanonicalAccountId,
                    CanonicalPrivateKeySeed),
            });

        using var response = await client.SendAsync(
            HttpMethod.Get,
            "/v1/query",
            accept: "application/json",
            configureRequest: request => request.Headers.TryAddWithoutValidation("X-Iroha-Test", "ok"),
            cancellationToken: TestContext.Current.CancellationToken);

        Assert.Equal("ok", Assert.Single(handler.LastRequest!.Headers.GetValues("X-Iroha-Test")));
        Assert.Equal("Bearer", handler.LastRequest.Headers.Authorization?.Scheme);
        Assert.True(handler.LastRequest.Headers.Contains("X-Iroha-Signature"));
    }

    [Theory]
    [InlineData("method")]
    [InlineData("uri")]
    [InlineData("content")]
    [InlineData("authorization")]
    [InlineData("accept")]
    [InlineData("signature")]
    public async Task SendAsyncRejectsConfigureRequestMutatingProtectedStateBeforeDispatch(string mutation)
    {
        using var handler = new RecordingHandler(_ =>
            throw new InvalidOperationException("mutated request reached HTTP dispatch"));
        using var content = new StringContent("{\"ok\":true}");
        using var client = new ToriiClient(
            new Uri("https://torii.example"),
            new HttpClient(handler),
            new ToriiClientOptions
            {
                BearerToken = "dev-token",
                CanonicalRequestCredentials = new CanonicalRequestCredentials(
                    CanonicalAccountId,
                    CanonicalPrivateKeySeed),
            });

        var error = await Assert.ThrowsAsync<ArgumentException>(() =>
            client.SendAsync(
                HttpMethod.Get,
                "/v1/query",
                content: content,
                accept: "application/json",
                configureRequest: request => MutateProtectedRequestState(request, mutation),
                cancellationToken: TestContext.Current.CancellationToken));

        Assert.Equal("configureRequest", error.ParamName);
        Assert.Null(handler.LastRequest);
    }

    [Fact]
    public async Task GetNodeCapabilitiesAsyncDeserializesTypedResponse()
    {
        const string responseBody = """
            {
              "abi_version": 1,
              "data_model_version": 1,
              "signed_transaction_schema_hash_hex": "eeeeeeeeeeeeeeeeeeeeeeeeeeeeeeee",
              "crypto": {
                "curves": {
                  "allowed_curve_bitmap": [26],
                  "allowed_curve_ids": [1, 3, 4],
                  "registry_version": 1
                },
                "sm": {
                  "acceleration": {
                    "neon_sm3": false,
                    "neon_sm4": false,
                    "policy": "scalar-only",
                    "scalar": true
                  },
                  "allowed_signing": ["ed25519", "secp256k1", "bls_normal"],
                  "default_hash": "blake2b-256",
                  "enabled": false,
                  "openssl_preview": false,
                  "sm2_distid_default": "1234567812345678"
                }
              },
              "query": {
                "aggregate": {
                  "exact_results": true,
                  "supported_resources": ["accounts", "assets"],
                  "v1": true
                },
                "indexed_snapshot_marker": true,
                "projection": {
                  "archive_export_v1": true,
                  "archive_version": 1,
                  "blob_class_custom_id": 1001,
                  "checkpoint_contract_v1": true,
                  "checkpoint_plan_v1": true,
                  "checkpoint_publish_v1": true,
                  "codec": "application/x-iroha-query-shard+norito+zstd",
                  "compression": "zstd",
                  "da_v1_enabled": false,
                  "default_partition_count": 4096,
                  "export_supported_resources": ["accounts"],
                  "latest_checkpoint_block_hash_hex": "8888888888888888888888888888888888888888888888888888888888888888",
                  "latest_checkpoint_indexed_height": 42,
                  "metadata_keys": ["query_projection.locator", "query_projection.resource", "query_projection.partition_id", "query_projection.asset_definition_id", "query_projection.indexed_height", "query_projection.indexed_block_hash_hex", "query_projection.row_count", "query_projection.rowset_codec", "query_projection.rowset_hash_hex", "query_projection.emitted_at_unix"],
                  "rowset_codec": "application/x-iroha-query-shard-rowset+norito",
                  "schema_version": 1,
                  "shard_catalog_v1": true
                },
                "row_enrichment_fields": ["primary_alias", "primary_alias_name", "primary_alias_dataspace", "primary_alias_domain", "has_primary_alias"]
              }
            }
            """;

        using var handler = new RecordingHandler(_ => new HttpResponseMessage(HttpStatusCode.OK)
        {
            Content = new StringContent(responseBody),
        });

        using var client = new ToriiClient(new Uri("https://torii.example"), new HttpClient(handler));
        var capabilities = await client.GetNodeCapabilitiesAsync(cancellationToken: TestContext.Current.CancellationToken);

        Assert.Equal(1, capabilities.AbiVersion);
        Assert.Equal(1, capabilities.DataModelVersion);
        Assert.Equal(SignedTransactionSchemaHashHex, capabilities.SignedTransactionSchemaHashHex);
        var allowedSigning = Assert.IsType<string[]>(capabilities.Crypto.Sm.AllowedSigning);
        var allowedCurveIds = Assert.IsType<int[]>(capabilities.Crypto.Curves.AllowedCurveIds);
        var allowedCurveBitmap = Assert.IsType<ulong[]>(capabilities.Crypto.Curves.AllowedCurveBitmap);
        var rowEnrichmentFields = Assert.IsType<string[]>(capabilities.Query.RowEnrichmentFields);
        var supportedResources = Assert.IsType<string[]>(capabilities.Query.Aggregate.SupportedResources);
        var metadataKeys = Assert.IsType<string[]>(capabilities.Query.Projection.MetadataKeys);
        var exportSupportedResources = Assert.IsType<string[]>(capabilities.Query.Projection.ExportSupportedResources);
        Assert.Equal(3, allowedCurveIds.Length);
        Assert.Contains("ed25519", allowedSigning);
        Assert.True(capabilities.Query.Aggregate.V1);
        Assert.Equal("application/x-iroha-query-shard+norito+zstd", capabilities.Query.Projection.Codec);
        allowedSigning[0] = "mutated";
        allowedCurveIds[0] = 99;
        allowedCurveBitmap[0] = 0;
        rowEnrichmentFields[0] = "mutated";
        supportedResources[0] = "mutated";
        metadataKeys[0] = "mutated";
        exportSupportedResources[0] = "mutated";
        Assert.Contains("ed25519", capabilities.Crypto.Sm.AllowedSigning);
        Assert.Equal(1, capabilities.Crypto.Curves.AllowedCurveIds[0]);
        Assert.Equal((ulong)26, capabilities.Crypto.Curves.AllowedCurveBitmap[0]);
        Assert.Equal("primary_alias", capabilities.Query.RowEnrichmentFields[0]);
        Assert.Equal("accounts", capabilities.Query.Aggregate.SupportedResources[0]);
        Assert.Equal("query_projection.locator", capabilities.Query.Projection.MetadataKeys[0]);
        Assert.Equal("accounts", capabilities.Query.Projection.ExportSupportedResources[0]);
        Assert.Equal("/v1/node/capabilities", handler.LastRequest!.RequestUri!.AbsolutePath);
    }

    [Fact]
    public void NodeCapabilitiesListsSnapshotInitAndAccessValues()
    {
        string[] allowedSigning = ["ed25519", "secp256k1"];
        var sm = new ToriiNodeSmCapabilities
        {
            Enabled = false,
            DefaultHash = "blake2b-256",
            AllowedSigning = allowedSigning,
            Sm2DistidDefault = "1234567812345678",
            OpensslPreview = false,
            Acceleration = new ToriiNodeSmAcceleration { Scalar = true, Policy = "scalar-only" },
        };
        int[] allowedCurveIds = [1, 3, 4];
        ulong[] allowedCurveBitmap = [26];
        var curves = new ToriiNodeCurveCapabilities
        {
            RegistryVersion = 1,
            AllowedCurveIds = allowedCurveIds,
            AllowedCurveBitmap = allowedCurveBitmap,
        };
        string[] rowEnrichmentFields = ["primary_alias"];
        string[] supportedResources = ["accounts"];
        var aggregate = new ToriiNodeAggregateQueryCapabilities
        {
            V1 = true,
            ExactResults = true,
            SupportedResources = supportedResources,
        };
        string[] metadataKeys = ["query_projection.locator"];
        string[] exportSupportedResources = ["accounts"];
        var projection = new ToriiNodeProjectionCapabilities
        {
            CheckpointContractV1 = true,
            CheckpointPlanV1 = true,
            CheckpointPublishV1 = true,
            ShardCatalogV1 = true,
            ArchiveExportV1 = true,
            ArchiveVersion = 1,
            SchemaVersion = 1,
            BlobClassCustomId = 1001,
            Codec = "application/x-iroha-query-shard+norito+zstd",
            RowsetCodec = "application/x-iroha-query-shard-rowset+norito",
            Compression = "zstd",
            DefaultPartitionCount = 4096,
            MetadataKeys = metadataKeys,
            ExportSupportedResources = exportSupportedResources,
        };
        var query = new ToriiNodeQueryCapabilities
        {
            Aggregate = aggregate,
            IndexedSnapshotMarker = true,
            RowEnrichmentFields = rowEnrichmentFields,
            Projection = projection,
        };

        allowedSigning[0] = "mutated";
        allowedCurveIds[0] = 99;
        allowedCurveBitmap[0] = 0;
        rowEnrichmentFields[0] = "mutated";
        supportedResources[0] = "mutated";
        metadataKeys[0] = "mutated";
        exportSupportedResources[0] = "mutated";

        AssertDetachedStringList(() => sm.AllowedSigning, "ed25519", "mutated-getter");
        AssertDetachedIntList(() => curves.AllowedCurveIds, 1, 99);
        AssertDetachedUInt64List(() => curves.AllowedCurveBitmap, 26, 0);
        AssertDetachedStringList(() => query.RowEnrichmentFields, "primary_alias", "mutated-getter");
        AssertDetachedStringList(() => aggregate.SupportedResources, "accounts", "mutated-getter");
        AssertDetachedStringList(() => projection.MetadataKeys, "query_projection.locator", "mutated-getter");
        AssertDetachedStringList(() => projection.ExportSupportedResources, "accounts", "mutated-getter");

        static void AssertDetachedStringList(Func<IReadOnlyList<string>> getter, string expectedFirst, string replacementFirst)
        {
            var detached = Assert.IsType<string[]>(getter());
            Assert.Equal(expectedFirst, detached[0]);
            detached[0] = replacementFirst;
            var stored = Assert.IsType<string[]>(getter());
            Assert.NotSame(detached, stored);
            Assert.Equal(expectedFirst, stored[0]);
        }

        static void AssertDetachedIntList(Func<IReadOnlyList<int>> getter, int expectedFirst, int replacementFirst)
        {
            var detached = Assert.IsType<int[]>(getter());
            Assert.Equal(expectedFirst, detached[0]);
            detached[0] = replacementFirst;
            var stored = Assert.IsType<int[]>(getter());
            Assert.NotSame(detached, stored);
            Assert.Equal(expectedFirst, stored[0]);
        }

        static void AssertDetachedUInt64List(Func<IReadOnlyList<ulong>> getter, ulong expectedFirst, ulong replacementFirst)
        {
            var detached = Assert.IsType<ulong[]>(getter());
            Assert.Equal(expectedFirst, detached[0]);
            detached[0] = replacementFirst;
            var stored = Assert.IsType<ulong[]>(getter());
            Assert.NotSame(detached, stored);
            Assert.Equal(expectedFirst, stored[0]);
        }
    }

    [Fact]
    public async Task GetNodeCapabilitiesAsyncAcceptsConsistentSm2Capabilities()
    {
        using var handler = new RecordingHandler(_ => JsonResponse(NodeCapabilitiesResponseJsonWithSm(
            "sm3-256",
            new JsonArray("ed25519", "sm2"))));
        using var client = new ToriiClient(new Uri("https://torii.example"), new HttpClient(handler));

        var capabilities = await client.GetNodeCapabilitiesAsync(cancellationToken: TestContext.Current.CancellationToken);

        Assert.Equal("sm3-256", capabilities.Crypto.Sm.DefaultHash);
        Assert.Contains("sm2", capabilities.Crypto.Sm.AllowedSigning);
    }

    public static IEnumerable<object?[]> InvalidNodeCapabilityResponses()
    {
        foreach (var field in RequiredNodeCapabilityScalarFields())
        {
            yield return new object?[]
            {
                field,
                RemoveNodeCapabilitiesResponseField(field),
                "must not be null",
            };
        }

        foreach (var field in RequiredNodeCapabilityStringFields())
        {
            yield return new object?[]
            {
                field,
                NodeCapabilitiesResponseJson(field, null),
                "must not be null",
            };
            yield return new object?[]
            {
                field,
                RemoveNodeCapabilitiesResponseField(field),
                "must not be null",
            };
        }

        foreach (var field in RequiredNodeCapabilityStringListElementFields())
        {
            yield return new object?[]
            {
                field,
                NodeCapabilitiesResponseJson(field, null),
                "must not be null",
            };
        }

        yield return new object?[] { "abi_version", NodeCapabilitiesResponseJson("abi_version", -1), "non-negative" };
        yield return new object?[] { "abi_version", NodeCapabilitiesResponseJson("abi_version", 0), "must be 1" };
        yield return new object?[] { "abi_version", NodeCapabilitiesResponseJson("abi_version", 2), "must be 1" };
        yield return new object?[]
        {
            "data_model_version",
            NodeCapabilitiesResponseJson("data_model_version", -1),
            "non-negative",
        };
        yield return new object?[]
        {
            "signed_transaction_schema_hash_hex",
            NodeCapabilitiesResponseJson("signed_transaction_schema_hash_hex", " " + SignedTransactionSchemaHashHex),
            "surrounding whitespace",
        };
        yield return new object?[]
        {
            "signed_transaction_schema_hash_hex",
            NodeCapabilitiesResponseJson(
                "signed_transaction_schema_hash_hex",
                SignedTransactionSchemaHashHex.ToUpperInvariant()),
            "lowercase hex",
        };
        yield return new object?[]
        {
            "signed_transaction_schema_hash_hex",
            NodeCapabilitiesResponseJson("signed_transaction_schema_hash_hex", SignedTransactionSchemaHashHex[..31]),
            "32-character",
        };
        yield return new object?[]
        {
