    [Fact]
    public void ExplorerEconometricsListsSnapshotInitAndAccessValues()
    {
        static void AssertSnapshot<T>(List<T> source, Func<IReadOnlyList<T>> getItems, T original, T replacement)
            where T : class
        {
            source.Add(replacement);
            var firstAccess = Assert.IsType<T[]>(getItems());
            Assert.Same(original, Assert.Single(firstAccess));
            firstAccess[0] = replacement;
            var secondAccess = Assert.IsType<T[]>(getItems());
            Assert.Same(original, Assert.Single(secondAccess));
        }

        var velocity = new ToriiExplorerEconometricsVelocityWindow
        {
            Key = "1h",
            StartMilliseconds = 120000,
            EndMilliseconds = 123456,
            Transfers = 2,
            UniqueSenders = 1,
            UniqueReceivers = 2,
            Amount = "10",
        };
        var replacementVelocity = velocity with { Key = "4h", Amount = "20" };
        var velocityItems = new List<ToriiExplorerEconometricsVelocityWindow> { velocity };
        var issuanceWindow = new ToriiExplorerEconometricsIssuanceWindow
        {
            Key = "24h",
            StartMilliseconds = 100000,
            EndMilliseconds = 123456,
            MintCount = 1,
            BurnCount = 0,
            Minted = "100",
            Burned = "0",
            Net = "100",
        };
        var replacementIssuanceWindow = issuanceWindow with { Key = "7d", Net = "200" };
        var issuanceWindowItems = new List<ToriiExplorerEconometricsIssuanceWindow> { issuanceWindow };
        var issuancePoint = new ToriiExplorerEconometricsIssuanceSeriesPoint
        {
            BucketStartMilliseconds = 86400,
            Minted = "100",
            Burned = "0",
            Net = "100",
        };
        var replacementIssuancePoint = issuancePoint with { BucketStartMilliseconds = 172800, Net = "200" };
        var issuanceSeriesItems = new List<ToriiExplorerEconometricsIssuanceSeriesPoint> { issuancePoint };
        var econometrics = new ToriiExplorerAssetDefinitionEconometrics
        {
            DefinitionId = "rose#wonderland.paynet",
            ComputedAtMilliseconds = 123456,
            VelocityWindows = velocityItems,
            IssuanceWindows = issuanceWindowItems,
            IssuanceSeries = issuanceSeriesItems,
        };

        AssertSnapshot(velocityItems, () => econometrics.VelocityWindows, velocity, replacementVelocity);
        AssertSnapshot(
            issuanceWindowItems,
            () => econometrics.IssuanceWindows,
            issuanceWindow,
            replacementIssuanceWindow);
        AssertSnapshot(
            issuanceSeriesItems,
            () => econometrics.IssuanceSeries,
            issuancePoint,
            replacementIssuancePoint);
        var roundTripEconometrics = Assert.IsType<ToriiExplorerAssetDefinitionEconometrics>(
            JsonSerializer.Deserialize<ToriiExplorerAssetDefinitionEconometrics>(
                JsonSerializer.Serialize(econometrics)));
        Assert.Equal("1h", Assert.Single(roundTripEconometrics.VelocityWindows).Key);
        Assert.Equal("24h", Assert.Single(roundTripEconometrics.IssuanceWindows).Key);
        Assert.Equal((ulong)86400, Assert.Single(roundTripEconometrics.IssuanceSeries).BucketStartMilliseconds);

        var lorenzPoint = new ToriiExplorerEconometricsLorenzPoint { Population = 0.0, Share = 0.0 };
        var replacementLorenzPoint = new ToriiExplorerEconometricsLorenzPoint { Population = 1.0, Share = 1.0 };
        var lorenzItems = new List<ToriiExplorerEconometricsLorenzPoint> { lorenzPoint };
        var distribution = new ToriiExplorerEconometricsDistributionSnapshot
        {
            Gini = 0.3,
            Hhi = 0.58,
            Theil = 0.1,
            Entropy = 0.6,
            EntropyNormalized = 0.8,
            Nakamoto33 = 1,
            Nakamoto51 = 1,
            Nakamoto67 = 2,
            Top1 = 0.7,
            Top5 = 1.0,
            Top10 = 1.0,
            Median = "300",
            P90 = "700",
            P99 = "700",
            Lorenz = lorenzItems,
        };

        AssertSnapshot(lorenzItems, () => distribution.Lorenz, lorenzPoint, replacementLorenzPoint);
        var roundTripDistribution = Assert.IsType<ToriiExplorerEconometricsDistributionSnapshot>(
            JsonSerializer.Deserialize<ToriiExplorerEconometricsDistributionSnapshot>(
                JsonSerializer.Serialize(distribution)));
        Assert.Equal(0.0, Assert.Single(roundTripDistribution.Lorenz).Population);

        var topHolder = new ToriiExplorerEconometricsTopHolder
        {
            AccountId = ExplorerTopHolderAccountId,
            Balance = "700",
        };
        var replacementTopHolder = topHolder with { AccountId = ExplorerDirectoryAccountId, Balance = "300" };
        var topHolderItems = new List<ToriiExplorerEconometricsTopHolder> { topHolder };
        var snapshot = new ToriiExplorerAssetDefinitionSnapshot
        {
            DefinitionId = "rose#wonderland.paynet",
            ComputedAtMilliseconds = 123456,
            HoldersTotal = 2,
            TotalSupply = "1000",
            TopHolders = topHolderItems,
            Distribution = distribution,
        };

        AssertSnapshot(topHolderItems, () => snapshot.TopHolders, topHolder, replacementTopHolder);
        var roundTripSnapshot = Assert.IsType<ToriiExplorerAssetDefinitionSnapshot>(
            JsonSerializer.Deserialize<ToriiExplorerAssetDefinitionSnapshot>(JsonSerializer.Serialize(snapshot)));
        Assert.Equal(ExplorerTopHolderAccountId, Assert.Single(roundTripSnapshot.TopHolders).AccountId);
    }

    [Fact]
    public async Task GetExplorerAssetsAsyncAddsFiltersAndDeserializesPage()
    {
        using var handler = new RecordingHandler(_ => new HttpResponseMessage(HttpStatusCode.OK)
        {
            Content = new StringContent($$"""
                {
                  "pagination": { "page": 4, "per_page": 1, "total_pages": 9, "total_items": 9 },
                  "items": [
                    {
                      "id": "asset-001",
                      "definition_id": "rose#wonderland.paynet",
                      "account_id": "{{ExplorerAssetAccountId}}",
                      "value": "25"
                    }
                  ]
                }
                """),
        });

        using var client = new ToriiClient(new Uri("https://torii.example"), new HttpClient(handler));
        var page = await client.GetExplorerAssetsAsync(new ToriiExplorerAssetsQuery
        {
            Page = 4,
            PerPage = 1,
            OwnedBy = ExplorerAssetAccountId,
            Definition = "rose#wonderland.paynet",
            AssetId = "asset-001",
        }, cancellationToken: TestContext.Current.CancellationToken);

        Assert.Equal((ulong)9, page.Pagination.TotalItems);
        Assert.Single(page.Items);
        Assert.Equal(ExplorerAssetAccountId, page.Items[0].AccountId);
        Assert.Equal("25", page.Items[0].Value);
        Assert.Equal(
            $"/v1/explorer/assets?page=4&per_page=1&owned_by={Uri.EscapeDataString(ExplorerAssetAccountId)}&definition=rose%23wonderland.paynet&asset_id=asset-001",
            handler.LastRequest!.RequestUri!.PathAndQuery);
    }

