    [Fact]
    public void RawExplorerDistributionWriteRejectsOutOfRangeRatio()
    {
        var response = new ToriiExplorerEconometricsDistributionSnapshot
        {
            Gini = 0.3,
            Hhi = 0.58,
            Theil = 0.1,
            Entropy = 0.6,
            EntropyNormalized = 0.8,
            Nakamoto33 = 1,
            Nakamoto51 = 1,
            Nakamoto67 = 2,
            Top1 = 0.7,
            Top5 = 1.0,
            Top10 = 1.0,
            Median = "300",
            P90 = "700",
            P99 = "700",
            Lorenz = [new ToriiExplorerEconometricsLorenzPoint { Population = 0.0, Share = 0.0 }],
        };
        var giniField = typeof(ToriiExplorerEconometricsDistributionSnapshot).GetField(
            "gini",
            System.Reflection.BindingFlags.Instance | System.Reflection.BindingFlags.NonPublic);
        Assert.NotNull(giniField);
        giniField.SetValue(response, 1.2);

        var error = Assert.Throws<JsonException>(() => JsonSerializer.Serialize(response));

        Assert.Contains("gini", error.Message);
        Assert.Contains("0 to 1", error.Message);
    }

