    [Fact]
    public void RawAccountPermissionPreservesArbitraryPayload()
    {
        var permission = JsonSerializer.Deserialize<ToriiAccountPermission>("""
            {
              "name": "CanResolveAccountAlias",
              "payload": { "dataspace": 7, "flags": [true, false], "note": "kept" }
