    [Fact]
    public async Task GetExplorerInstructionContractViewAsyncEncodesHashAndIndexAndDeserializesView()
    {
        using var handler = new RecordingHandler(_ => new HttpResponseMessage(HttpStatusCode.OK)
        {
            Content = new StringContent($$"""
                {
                  "code_hash": "{{ContractCodeHashHex}}",
                  "declared_code_hash": "{{ContractCodeHashHex}}",
                  "abi_hash": "{{ContractAbiHashHex}}",
                  "compiler_fingerprint": "kotodama-1",
                  "byte_len": 64,
                  "permissions": ["CanTransferUserAssets"],
                  "access_hints": {
                    "read_keys": ["balances"],
                    "write_keys": ["ledger"]
                  },
                  "entrypoints": [
                    {
                      "name": "main",
                      "kind": "kotoage",
                      "params": [
                        { "name": "amount", "type_name": "int" }
                      ],
                      "return_type": "bool",
                      "permission": "CanTransferUserAssets",
                      "read_keys": ["balances"],
                      "write_keys": ["ledger"],
                      "access_hints_complete": true,
                      "access_hints_skipped": [],
                      "triggers": ["after_transfer"]
                    }
                  ],
                  "analysis": {
                    "instruction_count": 42,
                    "memory": {
                      "load64": 1,
                      "store64": 2,
                      "load128": 3,
                      "store128": 4
                    },
                    "syscalls": [
                      { "number": 7, "name": "emit", "count": 3 }
                    ]
                  },
                  "warnings": ["historical bytes"],
                  "rendered_source_kind": "pseudo_source",
                  "rendered_source_text": "seiyaku Demo { kotoage fn main(int amount) -> bool authorize(\"CanTransferUserAssets\") {} }",
                  "verified_source_ref": {
                    "language": "kotodama",
                    "source_name": "demo.ko",
                    "submitted_at": "2026-03-29T12:00:00Z",
                    "manifest_id_hex": "{{VerifiedSourceManifestIdHex}}",
                    "payload_digest_hex": "{{VerifiedSourcePayloadDigestHex}}",
                    "content_length": 128
                  }
                }
                """),
        });

        using var client = new ToriiClient(new Uri("https://torii.example"), new HttpClient(handler));
        var view = await client.GetExplorerInstructionContractViewAsync("tx-detail", 2, cancellationToken: TestContext.Current.CancellationToken);

        Assert.Equal(ContractCodeHashHex, view.CodeHash);
        Assert.Equal(ContractCodeHashHex, view.DeclaredCodeHash);
        Assert.Equal("ledger", view.AccessHints!.WriteKeys[0]);
        Assert.Equal("amount", view.Entrypoints[0].Parameters[0].Name);
        Assert.Equal((ulong)42, view.Analysis!.InstructionCount);
        Assert.Equal("kotodama", view.VerifiedSourceReference!.Language);
        Assert.Equal("/v1/explorer/instructions/tx-detail/2/contract-view", handler.LastRequest!.RequestUri!.AbsolutePath);
    }

