    [Fact]
    public async Task LookupAliasesByAccountAsyncPostsOptionalScopeFilters()
    {
        using var handler = new RecordingHandler(request =>
        {
            var payload = ReadBodyAsJson(request);
            Assert.Equal("/v1/aliases/by-account", request.RequestUri!.AbsolutePath);
            Assert.Equal(CanonicalAccountId, payload.RootElement.GetProperty("account_id").GetString());
            Assert.Equal("universal", payload.RootElement.GetProperty("dataspace").GetString());
            Assert.Equal("paynet", payload.RootElement.GetProperty("domain").GetString());

            return new HttpResponseMessage(HttpStatusCode.OK)
            {
                Content = new StringContent($$"""
                    {
                      "account_id": "{{CanonicalAccountId}}",
                      "total": 2,
                      "source": "on_chain",
                      "items": [
                        {
                          "alias": "merchant@paynet.universal",
                          "dataspace": "universal",
                          "domain": "paynet",
                          "is_primary": true
                        },
                        {
                          "alias": "merchant@universal",
                          "dataspace": "universal",
                          "domain": null,
                          "is_primary": false
                        }
                      ]
                    }
                    """),
            };
        });

        using var client = new ToriiClient(new Uri("https://torii.example"), new HttpClient(handler));
        var aliases = await client.LookupAliasesByAccountAsync(CanonicalAccountId, dataspace: "universal", domain: "paynet", cancellationToken: TestContext.Current.CancellationToken);

        Assert.NotNull(aliases);
        Assert.Equal(CanonicalAccountId, aliases!.AccountId);
        Assert.Equal(2, aliases.Total);
        Assert.Equal("merchant@paynet.universal", aliases.Items[0].Alias);
        Assert.True(aliases.Items[0].IsPrimary);
        Assert.Equal("on_chain", aliases.Source);
    }

