    [Theory]
    [MemberData(nameof(InvalidDirectVpnResponseMetadata))]
    public void VpnResponseDtosRejectMalformedDirectMetadata(
        string operation,
        string propertyName,
        object? value)
    {
        var error = Assert.ThrowsAny<ArgumentException>(() =>
            SetVpnResponseDirectMetadata(operation, propertyName, value));

