    [Fact]
    public async Task GetSoraFsCidLookupAsyncDeserializesListing()
    {
        using var handler = new RecordingHandler(_ => new HttpResponseMessage(HttpStatusCode.OK)
        {
            Content = new StringContent($$"""
                {
                  "content_cid": "bafylookup",
                  "manifest_digest_hex": "{{SoraFsManifestDigestHex}}",
                  "manifest_id_hex": "{{SoraFsManifestIdHex}}",
                  "index_document": "index.html",
                  "files": [
                    {
                      "path": ["assets", "app main.js"],
                      "offset": 1,
                      "size": 2,
                      "first_chunk": 3,
                      "chunk_count": 4
                    }
                  ]
                }
                """),
        });

        using var client = new ToriiClient(new Uri("https://torii.example"), new HttpClient(handler));
        var lookup = await client.GetSoraFsCidLookupAsync("bafylookup", cancellationToken: TestContext.Current.CancellationToken);

        Assert.Equal("bafylookup", lookup.ContentCid);
        Assert.Equal(SoraFsManifestDigestHex, lookup.ManifestDigestHex);
        Assert.Equal(SoraFsManifestIdHex, lookup.ManifestIdHex);
        Assert.Equal("index.html", lookup.IndexDocument);
        var files = Assert.IsType<ToriiSoraFsFileEntry[]>(lookup.Files);
        Assert.Single(files);
        var path = Assert.IsType<string[]>(files[0].Path);
        Assert.Equal("assets", path[0]);
        Assert.Equal("app main.js", path[1]);
        files[0] = new ToriiSoraFsFileEntry { Path = ["mutated"], Offset = 9, Size = 9, FirstChunk = 9, ChunkCount = 9 };
        path[0] = "mutated";
        var refreshedFiles = Assert.IsType<ToriiSoraFsFileEntry[]>(lookup.Files);
        var refreshedPath = Assert.IsType<string[]>(refreshedFiles[0].Path);
        Assert.NotSame(files, refreshedFiles);
        Assert.NotSame(path, refreshedPath);
        Assert.Equal("assets", refreshedPath[0]);
        Assert.Equal("app main.js", refreshedPath[1]);
        Assert.Equal("/v1/sorafs/cid/bafylookup", handler.LastRequest!.RequestUri!.AbsolutePath);
    }

    [Fact]
    public void SoraFsResponseListsSnapshotInitAndAccessValues()
    {
        string[] filePath = ["assets", "app main.js"];
        var file = new ToriiSoraFsFileEntry
        {
            Path = filePath,
            Offset = 1,
            Size = 2,
            FirstChunk = 3,
            ChunkCount = 4,
        };
        ToriiSoraFsFileEntry[] files = [file];
        var lookup = new ToriiSoraFsCidLookupResponse
        {
            ContentCid = "bafylookup",
            ManifestDigestHex = SoraFsManifestDigestHex,
            ManifestIdHex = SoraFsManifestIdHex,
            Files = files,
        };
        filePath[0] = "mutated";
        files[0] = new ToriiSoraFsFileEntry { Path = ["mutated"], Offset = 9, Size = 9, FirstChunk = 9, ChunkCount = 9 };

        AssertDetachedStringList(() => file.Path, "assets");
        AssertDetachedObjectList(
            () => lookup.Files,
            file,
            new ToriiSoraFsFileEntry { Path = ["mutated"], Offset = 9, Size = 9, FirstChunk = 9, ChunkCount = 9 });

        static void AssertDetachedStringList(Func<IReadOnlyList<string>> getter, string expectedFirst)
        {
            var detached = Assert.IsType<string[]>(getter());
            Assert.Equal(expectedFirst, detached[0]);
            detached[0] = "mutated-getter";
            var stored = Assert.IsType<string[]>(getter());
            Assert.NotSame(detached, stored);
            Assert.Equal(expectedFirst, stored[0]);
        }

        static void AssertDetachedObjectList<T>(Func<IReadOnlyList<T>> getter, T expectedFirst, T replacementFirst)
            where T : class
        {
            var detached = Assert.IsType<T[]>(getter());
            Assert.Same(expectedFirst, detached[0]);
            detached[0] = replacementFirst;
            var stored = Assert.IsType<T[]>(getter());
            Assert.NotSame(detached, stored);
            Assert.Same(expectedFirst, stored[0]);
        }
    }

