        }

        foreach (var (request, paramName) in new (ToriiVerifyingKeyUpdateRequest Request, string ParamName)[]
        {
            (update with { Authority = VerifyingKeyAuthorityAccountId + " " }, "Authority"),
            (update with { Name = "vk_main " }, "Name"),
