    public static IEnumerable<object?[]> InvalidVpnAndSoraFsRouteIdentifiers()
    {
        var operations = new (string Operation, string ParamName)[]
        {
            ("vpn-get", "sessionId"),
            ("vpn-delete", "sessionId"),
            ("sorafs-cid-lookup", "cid"),
            ("sorafs-open-content", "cid"),
            ("sorafs-get-content", "cid"),
        };
        var invalidValues = new (string? Value, string ExpectedMessage)[]
        {
            (null, "null or whitespace"),
            ("", "null or whitespace"),
            (" value", "whitespace"),
            ("value ", "whitespace"),
            ("value\u0001", "control characters"),
        };

        foreach (var (operation, paramName) in operations)
        {
            foreach (var (value, expectedMessage) in invalidValues)
            {
                yield return new object?[] { operation, value, paramName, expectedMessage };
            }
        }

        var hexRouteOperations = new (string Operation, string ParamName)[]
        {
            ("vpn-get", "sessionId"),
            ("vpn-delete", "sessionId"),
        };
        var invalidSessionIds = new (string Value, string ExpectedMessage)[]
        {
            ("value with-space", "whitespace"),
            ("value\u00A0with-nbsp", "whitespace"),
            ("session-1", "32-byte hex string"),
            (new string('g', 64), "32-byte hex string"),
            (new string('a', 63), "32-byte hex string"),
        };
        foreach (var (operation, paramName) in hexRouteOperations)
        {
            foreach (var (value, expectedMessage) in invalidSessionIds)
            {
                yield return new object?[] { operation, value, paramName, expectedMessage };
            }
        }

        var cidRouteOperations = new (string Operation, string ParamName)[]
        {
            ("sorafs-cid-lookup", "cid"),
            ("sorafs-open-content", "cid"),
            ("sorafs-get-content", "cid"),
        };
        var invalidCids = new (string Value, string ExpectedMessage)[]
        {
            ("bafy root", "whitespace"),
            ("bafy\u00A0root", "whitespace"),
            ("Bafyroot", "lowercase multibase base32"),
            ("cidv1", "lowercase multibase base32"),
            ("bafylook0p", "lowercase multibase base32"),
        };
        foreach (var (operation, paramName) in cidRouteOperations)
        {
            foreach (var (value, expectedMessage) in invalidCids)
            {
                yield return new object?[] { operation, value, paramName, expectedMessage };
            }
        }
    }

