    [Theory]
    [MemberData(nameof(InvalidUaidManifestResponses))]
    public async Task GetUaidManifestsAsyncRejectsMalformedResponse(
        string expectedField,
        string json,
        string expectedMessage)
    {
        const string uaidHex = "0123456789abcdef0123456789abcdef0123456789abcdef0123456789abcdef";
        using var handler = new RecordingHandler(_ => JsonResponse(json));
        using var client = new ToriiClient(new Uri("https://torii.example"), new HttpClient(handler));

        var error = await Assert.ThrowsAsync<JsonException>(() =>
            client.GetUaidManifestsAsync($"uaid:{uaidHex}", cancellationToken: TestContext.Current.CancellationToken));

        Assert.Contains(expectedField, error.Message);
        Assert.Contains(expectedMessage, error.Message);
        Assert.Contains("/v1/space-directory/uaids/", handler.LastRequest!.RequestUri!.AbsoluteUri);
        Assert.Contains("/manifests", handler.LastRequest.RequestUri.AbsoluteUri);
    }

