    [InlineData("cmVq ZWN0ZWQ=", "whitespace")]
    [InlineData("cmVqZWN0ZWQ=\u00A0", "surrounding whitespace")]
    [InlineData("cmVqZWN0ZWQ=\u0001", "control characters")]
    [InlineData("not-base64", "valid base64")]
