            return new HttpResponseMessage(HttpStatusCode.Accepted)
            {
                Content = new StringContent($$"""
                    {
                      "account_id": "{{OnboardingFixtureAccountId}}",
                      "alias": "{{OnboardingFixtureAlias}}",
                      "tx_hash_hex": "{{ToriiTransactionHashHex}}",
