    [Fact]
    public async Task GetContractStateAsyncAddsQueryAndDeserializesResponse()
    {
        using var handler = new RecordingHandler(_ => new HttpResponseMessage(HttpStatusCode.OK)
        {
            Content = new StringContent("""
                {
                  "path": null,
                  "paths": ["balances/alice", "balances/bob"],
                  "prefix": null,
                  "entries": [
                    {
                      "path": "balances/alice",
                      "found": true,
                      "value_json": { "quantity": "1" }
                    },
                    {
                      "path": "balances/bob",
                      "found": false
                    }
                  ],
                  "offset": 0,
                  "limit": 2,
                  "next_offset": null
                }
                """),
        });

        using var client = new ToriiClient(new Uri("https://torii.example"), new HttpClient(handler));
        var response = await client.GetContractStateAsync(new ToriiContractStateQuery
        {
            Paths = ["balances/alice", "balances/bob"],
            IncludeValue = false,
            Decode = "json",
        }, cancellationToken: TestContext.Current.CancellationToken);

        Assert.Equal(2, response.Paths!.Count);
        Assert.Equal("1", response.Entries[0].ValueJson!["quantity"]!.GetValue<string>());
        Assert.False(response.Entries[1].Found);
        Assert.Equal("/v1/contracts/state?paths=balances%2Falice%2Cbalances%2Fbob&include_value=false&decode=json", handler.LastRequest!.RequestUri!.PathAndQuery);
    }

    [Fact]
    public async Task GetContractStateAsyncSnapshotsPathListsBeforeDispatchAndAccess()
    {
        string[] requestedPaths = ["balances/alice", "balances/bob"];
        var query = new ToriiContractStateQuery
        {
            Paths = requestedPaths,
            IncludeValue = false,
            Decode = "json",
        };

        requestedPaths[0] = "mutated-before-dispatch";
        var detachedQueryPaths = Assert.IsType<string[]>(query.Paths);
        detachedQueryPaths[1] = "mutated-getter";
        var storedQueryPaths = Assert.IsType<string[]>(query.Paths);
        Assert.NotSame(detachedQueryPaths, storedQueryPaths);
        Assert.Equal(["balances/alice", "balances/bob"], storedQueryPaths);

        using var handler = new RecordingHandler(_ =>
        {
            requestedPaths[1] = "mutated-in-handler";
            return new HttpResponseMessage(HttpStatusCode.OK)
            {
                Content = new StringContent("""
                    {
                      "path": null,
                      "paths": ["balances/alice", "balances/bob"],
                      "prefix": null,
                      "entries": [
                        {
                          "path": "balances/alice",
                          "found": true,
                          "value_json": { "quantity": "1" }
                        }
                      ],
                      "offset": 0,
                      "limit": 2,
                      "next_offset": null
                    }
                    """),
            };
        });

        using var client = new ToriiClient(new Uri("https://torii.example"), new HttpClient(handler));
        var response = await client.GetContractStateAsync(query, cancellationToken: TestContext.Current.CancellationToken);

        Assert.Equal("/v1/contracts/state?paths=balances%2Falice%2Cbalances%2Fbob&include_value=false&decode=json", handler.LastRequest!.RequestUri!.PathAndQuery);
        var detachedResponsePaths = Assert.IsType<string[]>(response.Paths);
        detachedResponsePaths[0] = "mutated-response-getter";
        var storedResponsePaths = Assert.IsType<string[]>(response.Paths);
        Assert.NotSame(detachedResponsePaths, storedResponsePaths);
        Assert.Equal(["balances/alice", "balances/bob"], storedResponsePaths);
    }

    [Fact]
    public void IdentifierAndContractResponseListsSnapshotInitAndAccessValues()
    {
        static void AssertSnapshot<T>(List<T> source, Func<IReadOnlyList<T>> getItems, T original, T replacement)
            where T : class
        {
            source.Add(replacement);
            var firstAccess = Assert.IsType<T[]>(getItems());
            Assert.Same(original, Assert.Single(firstAccess));
            firstAccess[0] = replacement;
            var secondAccess = Assert.IsType<T[]>(getItems());
            Assert.Same(original, Assert.Single(secondAccess));
        }

        var policy = IdentifierPolicySummaryObject();
        var replacementPolicy = policy with { PolicyId = "email#retail" };
        var policyItems = new List<ToriiIdentifierPolicySummary> { policy };
        var policies = new ToriiIdentifierPoliciesResponse
        {
            Total = 1,
            Items = policyItems,
        };

        AssertSnapshot(policyItems, () => policies.Items, policy, replacementPolicy);
        var roundTripPolicies = Assert.IsType<ToriiIdentifierPoliciesResponse>(
            JsonSerializer.Deserialize<ToriiIdentifierPoliciesResponse>(JsonSerializer.Serialize(policies)));
        Assert.Equal("phone#retail", Assert.Single(roundTripPolicies.Items).PolicyId);

        var instance = new ToriiContractInstance
        {
            ContractId = "router::dex.universal",
            CodeHashHex = ContractCodeHashHex,
        };
        var replacementInstance = instance with { ContractId = "router::payments.universal" };
        var instances = new List<ToriiContractInstance> { instance };
        var instanceResponse = new ToriiContractInstancesResponse
        {
            Namespace = "universal",
            Instances = instances,
            Total = 1,
            Offset = 0,
            Limit = 1,
        };

        AssertSnapshot(instances, () => instanceResponse.Instances, instance, replacementInstance);
        var roundTripInstances = Assert.IsType<ToriiContractInstancesResponse>(
            JsonSerializer.Deserialize<ToriiContractInstancesResponse>(
                JsonSerializer.Serialize(instanceResponse)));
        Assert.Equal("router::dex.universal", Assert.Single(roundTripInstances.Instances).ContractId);

        var entry = new ToriiContractStateEntry
        {
            Path = "balances/alice",
            Found = true,
            ValueJson = new JsonObject
            {
                ["quantity"] = "1",
            },
        };
        var replacementEntry = new ToriiContractStateEntry
        {
            Path = "balances/bob",
            Found = false,
        };
        var entries = new List<ToriiContractStateEntry> { entry };
        var stateResponse = new ToriiContractStateResponse
        {
            Paths = ["balances/alice"],
            Entries = entries,
            Offset = 0,
            Limit = 1,
        };

        AssertSnapshot(entries, () => stateResponse.Entries, entry, replacementEntry);
        var roundTripState = Assert.IsType<ToriiContractStateResponse>(
            JsonSerializer.Deserialize<ToriiContractStateResponse>(JsonSerializer.Serialize(stateResponse)));
        Assert.Equal("balances/alice", Assert.Single(roundTripState.Entries).Path);
    }

