    [Fact]
    public void RawContractViewDiagnosticWriteRejectsNonPositiveLimits()
    {
        var valid = JsonSerializer.Deserialize<ToriiContractViewVmDiagnostic>(
            ContractViewDiagnosticRawJson("trap_kind", "Validation"))!;

        foreach (var (fieldName, field) in new[]
        {
            ("gasLimit", "gas_limit"),
            ("maxCycles", "max_cycles"),
            ("stackLimitBytes", "stack_limit_bytes"),
        })
        {
            var diagnostic = valid with { };
            SetPrivateField(diagnostic, fieldName, 0UL);

            var error = Assert.Throws<JsonException>(() => JsonSerializer.Serialize(diagnostic));

            Assert.Contains(field, error.Message);
            Assert.Contains("positive", error.Message);
        }
    }

