    [Fact]
    public async Task GetContractCodeViewAsyncEncodesCodeHashAndDeserializesView()
    {
        using var handler = new RecordingHandler(_ => new HttpResponseMessage(HttpStatusCode.OK)
        {
            Content = new StringContent($$"""
                {
                  "code_hash": "{{ContractCodeHashHex}}",
                  "declared_code_hash": null,
                  "abi_hash": "{{ContractAbiHashHex}}",
                  "compiler_fingerprint": "torii-tests",
                  "byte_len": 256,
                  "permissions": [],
                  "access_hints": null,
                  "entrypoints": [],
                  "analysis": null,
                  "warnings": ["verified source record loaded"],
                  "rendered_source_kind": "verified_source",
                  "rendered_source_text": "seiyaku Demo { view fn main() {} }",
                  "verified_source_ref": {
                    "language": "kotodama",
                    "source_name": "demo.ko",
                    "submitted_at": "2026-03-29T12:30:00Z",
                    "manifest_id_hex": "{{VerifiedSourceManifestIdHex}}",
                    "payload_digest_hex": "{{VerifiedSourcePayloadDigestHex}}",
                    "content_length": 24
                  }
                }
                """),
        });

        using var client = new ToriiClient(new Uri("https://torii.example"), new HttpClient(handler));
        var view = await client.GetContractCodeViewAsync(ContractCodeHashHex, cancellationToken: TestContext.Current.CancellationToken);

