        Assert.Equal((ulong)24, view.VerifiedSourceReference!.ContentLength);
        Assert.Equal($"/v1/contracts/code/{ContractCodeHashHex}/contract-view", handler.LastRequest!.RequestUri!.AbsolutePath);
    }

    [Fact]
    public void ContractCodeViewListsSnapshotInitAndAccessValues()
    {
        string[] accessReadKeys = ["contract:state/balance"];
        string[] accessWriteKeys = ["contract:state/ledger"];
        var accessHints = new ToriiContractViewAccessHints
        {
            ReadKeys = accessReadKeys,
            WriteKeys = accessWriteKeys,
        };
        var parameter = new ToriiContractViewEntrypointParam { Name = "amount", TypeName = "u128" };
        ToriiContractViewEntrypointParam[] parameters = [parameter];
        string[] entryReadKeys = ["contract:state/balance"];
        string[] entryWriteKeys = ["contract:state/ledger"];
        string[] skipped = ["dynamic_key"];
        string[] triggers = ["after_transfer"];
        var entrypoint = new ToriiContractViewEntrypoint
        {
            Name = "main",
            Kind = "call",
            Parameters = parameters,
            ReturnType = "bool",
            Permission = "can_execute_contract",
            ReadKeys = entryReadKeys,
            WriteKeys = entryWriteKeys,
            AccessHintsComplete = true,
            AccessHintsSkipped = skipped,
            Triggers = triggers,
        };
        var syscall = new ToriiContractViewSyscall { Number = 7, Name = "log", Count = 1 };
        ToriiContractViewSyscall[] syscalls = [syscall];
        var analysis = new ToriiContractViewAnalysis
        {
            InstructionCount = 42,
            Memory = new ToriiContractViewMemory { Load64 = 1, Store64 = 2, Load128 = 3, Store128 = 4 },
            Syscalls = syscalls,
        };
        string[] permissions = ["can_execute_contract"];
        ToriiContractViewEntrypoint[] entrypoints = [entrypoint];
        string[] warnings = ["verified source record loaded"];
        var view = new ToriiContractCodeView
        {
            CodeHash = ContractCodeHashHex,
            DeclaredCodeHash = ContractCodeHashHex,
            AbiHash = ContractAbiHashHex,
            Permissions = permissions,
            AccessHints = accessHints,
            Entrypoints = entrypoints,
            Analysis = analysis,
            Warnings = warnings,
            RenderedSourceKind = "verified_source",
            RenderedSourceText = "seiyaku Demo { view fn main() {} }",
        };

        accessReadKeys[0] = "mutated";
        accessWriteKeys[0] = "mutated";
        parameters[0] = new ToriiContractViewEntrypointParam { Name = "mutated", TypeName = "u64" };
        entryReadKeys[0] = "mutated";
        entryWriteKeys[0] = "mutated";
        skipped[0] = "mutated";
        triggers[0] = "mutated";
        syscalls[0] = new ToriiContractViewSyscall { Number = 8, Name = "mutated", Count = 2 };
        permissions[0] = "mutated";
        entrypoints[0] = new ToriiContractViewEntrypoint { Name = "mutated", Kind = "call" };
        warnings[0] = "mutated";

        AssertDetachedStringList(() => accessHints.ReadKeys, "contract:state/balance", "mutated-getter");
        AssertDetachedStringList(() => accessHints.WriteKeys, "contract:state/ledger", "mutated-getter");
        AssertDetachedObjectList(
            () => entrypoint.Parameters,
            parameter,
            new ToriiContractViewEntrypointParam { Name = "mutated", TypeName = "u64" });
        AssertDetachedStringList(() => entrypoint.ReadKeys, "contract:state/balance", "mutated-getter");
        AssertDetachedStringList(() => entrypoint.WriteKeys, "contract:state/ledger", "mutated-getter");
        AssertDetachedStringList(() => entrypoint.AccessHintsSkipped, "dynamic_key", "mutated-getter");
        AssertDetachedStringList(() => entrypoint.Triggers, "after_transfer", "mutated-getter");
        AssertDetachedObjectList(
            () => analysis.Syscalls,
            syscall,
            new ToriiContractViewSyscall { Number = 8, Name = "mutated", Count = 2 });
        AssertDetachedStringList(() => view.Permissions, "can_execute_contract", "mutated-getter");
        AssertDetachedObjectList(
            () => view.Entrypoints,
            entrypoint,
            new ToriiContractViewEntrypoint { Name = "mutated", Kind = "call" });
        AssertDetachedStringList(() => view.Warnings, "verified source record loaded", "mutated-getter");

        var deserialized = Assert.IsType<ToriiContractCodeView>(JsonSerializer.Deserialize<ToriiContractCodeView>(
            ContractCodeViewResponseJson(ContractCodeHashHex, ContractCodeHashHex, ContractAbiHashHex)));
        var deserializedAccessHints = Assert.IsType<ToriiContractViewAccessHints>(deserialized.AccessHints);
        var deserializedEntrypoints = Assert.IsType<ToriiContractViewEntrypoint[]>(deserialized.Entrypoints);
        var deserializedAnalysis = Assert.IsType<ToriiContractViewAnalysis>(deserialized.Analysis);
        var deserializedPermissions = Assert.IsType<string[]>(deserialized.Permissions);
        var deserializedWarnings = Assert.IsType<string[]>(deserialized.Warnings);
        var deserializedAccessReadKeys = Assert.IsType<string[]>(deserializedAccessHints.ReadKeys);
        var deserializedParameters = Assert.IsType<ToriiContractViewEntrypointParam[]>(deserializedEntrypoints[0].Parameters);
        var deserializedSyscalls = Assert.IsType<ToriiContractViewSyscall[]>(deserializedAnalysis.Syscalls);

        deserializedPermissions[0] = "mutated";
        deserializedWarnings[0] = "mutated";
        deserializedAccessReadKeys[0] = "mutated";
        deserializedEntrypoints[0] = new ToriiContractViewEntrypoint { Name = "mutated", Kind = "call" };
        deserializedParameters[0] = new ToriiContractViewEntrypointParam { Name = "mutated", TypeName = "u64" };
        deserializedSyscalls[0] = new ToriiContractViewSyscall { Number = 8, Name = "mutated", Count = 2 };

        Assert.Equal("can_execute_contract", deserialized.Permissions[0]);
        Assert.Equal("verified source record loaded", deserialized.Warnings[0]);
        Assert.Equal("contract:state/balance", deserializedAccessHints.ReadKeys[0]);
        Assert.Equal("main", deserialized.Entrypoints[0].Name);
        Assert.Equal("amount", deserialized.Entrypoints[0].Parameters[0].Name);
        Assert.Equal((byte)7, deserializedAnalysis.Syscalls[0].Number);

        static void AssertDetachedStringList(Func<IReadOnlyList<string>> getter, string expectedFirst, string replacementFirst)
        {
            var detached = Assert.IsType<string[]>(getter());
            Assert.Equal(expectedFirst, detached[0]);
            detached[0] = replacementFirst;
            var stored = Assert.IsType<string[]>(getter());
            Assert.NotSame(detached, stored);
            Assert.Equal(expectedFirst, stored[0]);
        }

        static void AssertDetachedObjectList<T>(Func<IReadOnlyList<T>> getter, T expectedFirst, T replacementFirst)
            where T : class
        {
            var detached = Assert.IsType<T[]>(getter());
            Assert.Same(expectedFirst, detached[0]);
            detached[0] = replacementFirst;
            var stored = Assert.IsType<T[]>(getter());
            Assert.NotSame(detached, stored);
            Assert.Same(expectedFirst, stored[0]);
        }
    }

    [Fact]
    public async Task ExecuteContractViewAsyncEncodesRequestAndDeserializesSuccess()
    {
        using var handler = new RecordingHandler(request =>
        {
            var payload = ReadBodyAsJson(request);
            Assert.Equal(ContractAuthorityAccountId, payload.RootElement.GetProperty("authority").GetString());

            return new HttpResponseMessage(HttpStatusCode.OK)
            {
                Content = new StringContent($$"""
                {
                  "ok": true,
                  "dataspace": "universal",
                  "contract_id": "router::dex.universal",
                  "contract_address": "iroha1qqqqqqqqqqqqqqqqqqqqqqqqqqqqqqqqqqqqqqqqqqqqqqqqqqqqqqqqqqqqqqqq",
                  "code_hash_hex": "{{ContractCodeHashHex}}",
                  "abi_hash_hex": "{{ContractAbiHashHex}}",
                  "entrypoint": "main",
                  "result": {
                    "status": "ok",
                    "matched": 2
                  }
                }
                """),
            };
        });

        using var client = new ToriiClient(new Uri("https://torii.example"), new HttpClient(handler));
        var result = await client.ExecuteContractViewAsync(new ToriiContractViewRequest
        {
            Authority = ContractAuthorityAccountId,
            ContractAlias = "router::dex.universal",
            Entrypoint = "main",
            Payload = JsonNode.Parse("""{ "amount": "1" }"""),
            GasLimit = 500_000,
        }, cancellationToken: TestContext.Current.CancellationToken);

        Assert.True(result.IsSuccess);
        Assert.NotNull(result.Success);
        Assert.Null(result.Error);
        Assert.Equal("router::dex.universal", result.Success!.ContractId);
        Assert.Equal("ok", result.Success.Result!["status"]!.GetValue<string>());
        Assert.Equal("/v1/contracts/view", handler.LastRequest!.RequestUri!.AbsolutePath);
    }

    [Fact]
    public async Task ExecuteContractViewAsyncDeserializesValidationFailure()
    {
        using var handler = new RecordingHandler(_ => new HttpResponseMessage(HttpStatusCode.UnprocessableEntity)
        {
            Content = new StringContent($$"""
                {
                  "ok": false,
                  "dataspace": "universal",
                  "contract_id": "router::dex.universal",
                  "contract_address": null,
                  "code_hash_hex": "{{ContractCodeHashHex}}",
                  "abi_hash_hex": "{{ContractAbiHashHex}}",
                  "entrypoint": "main",
                  "error": "view entrypoint rejected payload",
                  "vm_diagnostic": {
                    "trap_kind": "Validation",
                    "message": "missing field `amount`",
                    "pc": 12,
                    "function": "main",
                    "source_path": "contracts/router.ko",
                    "line": 4,
                    "column": 9,
                    "gas_limit": 500000,
                    "gas_remaining": 499900,
                    "gas_used": 100,
                    "cycles": 20,
                    "max_cycles": 500000,
                    "stack_limit_bytes": 8192,
                    "stack_bytes_used": 256,
                    "entrypoint_pc": 10,
                    "current_function": "main",
                    "opcode": 34,
                    "syscall": 7,
                    "predecoded_loaded": true,
                    "predecoded_hit": false
                  }
                }
                """),
        });

        using var client = new ToriiClient(new Uri("https://torii.example"), new HttpClient(handler));
        var result = await client.ExecuteContractViewAsync(new ToriiContractViewRequest
        {
            Authority = ContractAuthorityAccountId,
            ContractAlias = "router::dex.universal",
            GasLimit = 500_000,
        }, cancellationToken: TestContext.Current.CancellationToken);

        Assert.False(result.IsSuccess);
        Assert.Null(result.Success);
        Assert.NotNull(result.Error);
        Assert.Equal("view entrypoint rejected payload", result.Error!.Error);
        Assert.Equal((ulong)100, result.Error.VmDiagnostic!.GasUsed);
        Assert.Equal((ushort)34, result.Error.VmDiagnostic.Opcode);
    }

