    [Theory]
    [MemberData(nameof(InvalidMultisigContractCallProposeRequests))]
    public async Task ProposeMultisigContractCallAsyncRejectsMalformedRequestBeforeDispatch(
        ToriiMultisigContractCallProposeRequest request,
        string expectedParamName,
        string expectedMessage)
    {
        using var handler = new RecordingHandler(_ =>
            throw new InvalidOperationException("malformed multisig contract-call proposal reached HTTP dispatch"));
        using var client = new ToriiClient(new Uri("https://torii.example"), new HttpClient(handler));

        var error = await Assert.ThrowsAnyAsync<ArgumentException>(() =>
            client.ProposeMultisigContractCallAsync(request, cancellationToken: TestContext.Current.CancellationToken));

        Assert.Equal(expectedParamName, error.ParamName);
        Assert.Contains(expectedMessage, error.Message);
        Assert.Null(handler.LastRequest);
    }

