        yield return new object[] { " " + validCodeHash, valid, "codeHash", "whitespace" };
        yield return new object[] { new string('a', 63), valid, "codeHash", "32-byte hex string" };
        yield return new object[] { new string('g', 64), valid, "codeHash", "32-byte hex string" };
        yield return new object[] { validCodeHash, valid with { Language = " kotodama" }, "Language", "whitespace" };
        yield return new object[] { validCodeHash, valid with { Language = "Kotodama" }, "Language", "kotodama" };
        yield return new object[] { validCodeHash, valid with { Language = "rust" }, "Language", "kotodama" };
        yield return new object[] { validCodeHash, valid with { SourceName = "demo\u0001.ko" }, "SourceName", "control characters" };
        yield return new object[] { validCodeHash, valid with { SourceText = "" }, "SourceText", "null or whitespace" };
        yield return new object[] { validCodeHash, valid with { SourceText = "   " }, "SourceText", "null or whitespace" };
    }

