                {
                  "job_id": "job-1",
                  "code_hash": "{{ContractCodeHashHex}}",
                  "status": "mismatch",
                  "submitted_at": "2026-03-29T13:00:00Z",
                  "completed_at": "2026-03-29T13:00:02Z",
