    [Fact]
    public async Task GetRuntimeEndpointsDeserializeTypedPayloads()
    {
        using var handler = new RecordingHandler(request =>
        {
            var body = request.RequestUri!.AbsolutePath switch
            {
                "/v1/runtime/abi/active" => """{ "abi_version": 1 }""",
                "/v1/runtime/abi/hash" => $$"""{ "policy": "V1", "abi_hash_hex": "{{ContractAbiHashHex}}" }""",
                "/v1/runtime/metrics" => """
                    {
                      "abi_version": 1,
                      "upgrade_events_total": {
                        "proposed": 2,
                        "activated": 1,
                        "canceled": 0
                      }
                    }
                    """,
                _ => throw new InvalidOperationException("Unexpected route."),
            };

            return new HttpResponseMessage(HttpStatusCode.OK)
            {
                Content = new StringContent(body),
            };
        });

        using var client = new ToriiClient(new Uri("https://torii.example"), new HttpClient(handler));

        var active = await client.GetRuntimeAbiActiveAsync(cancellationToken: TestContext.Current.CancellationToken);
        var hash = await client.GetRuntimeAbiHashAsync(cancellationToken: TestContext.Current.CancellationToken);
        var metrics = await client.GetRuntimeMetricsAsync(cancellationToken: TestContext.Current.CancellationToken);

        Assert.Equal(1, active.AbiVersion);
        Assert.Equal("V1", hash.Policy);
        Assert.Equal(ContractAbiHashHex, hash.AbiHashHex);
        Assert.Equal(2, metrics.UpgradeEventsTotal.Proposed);
        Assert.Equal(1, metrics.UpgradeEventsTotal.Activated);
    }

