    private static object? DeserializeRawContractMetadata(string operation, string json)
    {
        return operation switch
        {
            "contract-code" => JsonSerializer.Deserialize<ToriiContractCodeRecord>(json),
            "contract-code-view" => JsonSerializer.Deserialize<ToriiContractCodeView>(json),
            "access-hints" => JsonSerializer.Deserialize<ToriiContractViewAccessHints>(json),
            "entrypoint" => JsonSerializer.Deserialize<ToriiContractViewEntrypoint>(json),
            "entrypoint-param" => JsonSerializer.Deserialize<ToriiContractViewEntrypointParam>(json),
            "analysis" => JsonSerializer.Deserialize<ToriiContractViewAnalysis>(json),
            "syscall" => JsonSerializer.Deserialize<ToriiContractViewSyscall>(json),
            "memory" => JsonSerializer.Deserialize<ToriiContractViewMemory>(json),
            "verified-source-ref" => JsonSerializer.Deserialize<ToriiContractVerifiedSourceReference>(json),
            "verified-source-job" => JsonSerializer.Deserialize<ToriiContractVerifiedSourceJob>(json),
            _ => throw new ArgumentOutOfRangeException(nameof(operation), operation, "Unknown contract metadata operation."),
        };
    }

    private static void DeserializeRawRuntimeMetadata(string operation, string json)
    {
        switch (operation)
        {
            case "runtime-abi-active":
                _ = JsonSerializer.Deserialize<ToriiRuntimeAbiActive>(json);
                break;
            case "runtime-metrics":
                _ = JsonSerializer.Deserialize<ToriiRuntimeMetrics>(json);
                break;
            case "runtime-abi-hash":
                _ = JsonSerializer.Deserialize<ToriiRuntimeAbiHash>(json);
                break;
            default:
                throw new ArgumentOutOfRangeException(
                    nameof(operation),
                    operation,
                    "Unknown runtime metadata operation.");
        }
    }

