            "sorafs-cid-lookup" => client.GetSoraFsCidLookupAsync(value!),
            "sorafs-open-content" => client.OpenSoraFsCidContentAsync(value!),
            "sorafs-get-content" => client.GetSoraFsCidContentAsync(value!),
