    private static Task InvokeVpnResponseOperationAsync(ToriiClient client, string operation)
    {
        return operation switch
        {
            "profile" => client.GetVpnProfileAsync(),
            "quote" => client.CreateVpnQuoteAsync(new ToriiVpnQuoteCreateRequest
            {
                ExitClass = "standard",
                MeteringPublicKeyHex = VpnMeteringPublicKeyHex,
            }),
            "session-create" => client.CreateVpnSessionAsync(new ToriiVpnSessionCreateRequest
            {
                ExitClass = "standard",
                QuoteId = VpnQuoteIdHex,
                PaymentTransactionHash = VpnPaymentTransactionHashHex,
                MeteringPublicKeyHex = VpnMeteringPublicKeyHex,
            }),
            "session-get" => client.GetVpnSessionAsync(VpnSessionIdHex),
            "receipt-submit" => client.SubmitVpnReceiptAsync(new ToriiVpnReceiptSubmitRequest
            {
                RelayReceiptHex = "abcd",
                ClientVoucherHex = "beef",
                LeaseIdHex = VpnQuoteIdHex,
            }),
            "receipt-list" => client.ListVpnReceiptsAsync(),
            "receipt-delete" => client.DeleteVpnSessionAsync(VpnSessionIdHex),
            _ => throw new ArgumentOutOfRangeException(nameof(operation), operation, "Unknown VPN response operation."),
        };
    }

    private static HttpStatusCode VpnSuccessStatusCode(string operation)
    {
        return operation switch
        {
            "quote" or "session-create" or "receipt-submit" => HttpStatusCode.Created,
            "profile" or "session-get" or "receipt-list" or "receipt-delete" => HttpStatusCode.OK,
            _ => throw new ArgumentOutOfRangeException(nameof(operation), operation, "Unknown VPN response operation."),
        };
    }

    private static ToriiClient CreateSignedVpnClient(RecordingHandler handler)
    {
        return new ToriiClient(
