    private static string SerializeRawVpnResponseWithAccountId(
        string operation,
        string field,
        string accountId)
    {
        return (operation, field) switch
        {
            ("profile", "escrow_account_id") => SerializeWithPrivateField(ValidVpnProfile(), "escrowAccountId", accountId),
            ("profile", "operator_account_id") => SerializeWithPrivateField(ValidVpnProfile(), "operatorAccountId", accountId),
            ("quote", "account_id") => SerializeWithPrivateField(ValidVpnQuote(), "accountId", accountId),
            ("quote", "escrow_account_id") => SerializeWithPrivateField(ValidVpnQuote(), "escrowAccountId", accountId),
            ("quote", "operator_account_id") => SerializeWithPrivateField(ValidVpnQuote(), "operatorAccountId", accountId),
            ("session", "account_id") => SerializeWithPrivateField(ValidVpnSession(), "accountId", accountId),
            ("session", "escrow_account_id") => SerializeWithPrivateField(ValidVpnSession(), "escrowAccountId", accountId),
            ("session", "operator_account_id") => SerializeWithPrivateField(ValidVpnSession(), "operatorAccountId", accountId),
            ("receipt", "account_id") => SerializeWithPrivateField(ValidVpnReceipt(), "accountId", accountId),
            ("receipt", "escrow_account_id") => SerializeWithPrivateField(ValidVpnReceipt(), "escrowAccountId", accountId),
            ("receipt", "operator_account_id") => SerializeWithPrivateField(ValidVpnReceipt(), "operatorAccountId", accountId),
            ("receipt-list", "items[0].account_id") => SerializeVpnReceiptListWithPrivateReceiptField(
                "accountId",
                accountId),
            ("receipt-list", "items[0].escrow_account_id") => SerializeVpnReceiptListWithPrivateReceiptField(
                "escrowAccountId",
                accountId),
            ("receipt-list", "items[0].operator_account_id") => SerializeVpnReceiptListWithPrivateReceiptField(
                "operatorAccountId",
                accountId),
            _ => throw new ArgumentOutOfRangeException(nameof(field), field, "Unknown VPN account response field."),
        };
    }

    private static string SerializeVpnReceiptListWithPrivateReceiptField(string fieldName, object? value)
    {
        var receipt = ValidVpnReceipt();
        var response = new ToriiVpnReceiptListResponse
        {
            Items = new[] { receipt },
            Total = 1,
        };
        SetPrivateField(receipt, fieldName, value);
        return JsonSerializer.Serialize(response);
    }

