    private static Task InvokeAliasResolveOperationAsync(
        ToriiClient client,
        string operation,
        string? value)
    {
        return operation switch
        {
            "account" => client.ResolveAccountAliasAsync(value!),
            "asset" => client.ResolveAssetAliasAsync(value!),
            "contract" => client.ResolveContractAliasAsync(value!),
            _ => throw new ArgumentOutOfRangeException(nameof(operation), operation, "Unknown alias resolve operation."),
        };
    }

