    private static string ExplorerResponseJson(string operation, string field, object? value)
    {
        var block = ExplorerBlockJsonObject();
        var transaction = ExplorerTransactionJsonObject();
        var transactionDetail = ExplorerTransactionDetailJsonObject();
        var instruction = ExplorerInstructionJsonObject();

        var root = operation switch
        {
            "blocks-page" => ExplorerPageJsonObject(block),
            "block" => block,
            "transactions-page" => ExplorerPageJsonObject(transaction),
            "transactions-latest" => ExplorerLatestJsonObject(transaction),
            "transaction-detail" => transactionDetail,
            "instructions-page" => ExplorerPageJsonObject(instruction),
            "instructions-latest" => ExplorerLatestJsonObject(instruction),
            "instruction-detail" => instruction,
            _ => throw new ArgumentOutOfRangeException(nameof(operation), operation, "Unknown explorer response operation."),
        };

        var target = operation switch
        {
            "blocks-page" or "block" => block,
            "transactions-page" or "transactions-latest" => transaction,
            "transaction-detail" => transactionDetail,
            "instructions-page" or "instructions-latest" or "instruction-detail" => instruction,
            _ => throw new ArgumentOutOfRangeException(nameof(operation), operation, "Unknown explorer response operation."),
        };

        if (ReferenceEquals(value, MissingExplorerField))
        {
            RemoveExplorerResponseField(root, target, field);
            return root.ToJsonString();
        }

        switch (field)
        {
            case "pagination.page":
                ((JsonObject)root["pagination"]!)["page"] = JsonValueForExplorer(value);
                break;
            case "pagination.per_page":
                ((JsonObject)root["pagination"]!)["per_page"] = JsonValueForExplorer(value);
                break;
            case "items":
                root["items"] = JsonValueForExplorer(value);
                break;
            case "items[0].hash":
            case "hash":
                target["hash"] = JsonValueForExplorer(value);
                break;
            case "transactions_hash":
                target["transactions_hash"] = JsonValueForExplorer(value);
                break;
            case "items[0].created_at":
            case "created_at":
                target["created_at"] = JsonValueForExplorer(value);
                break;
            case "items[0].status":
            case "status":
                target["status"] = JsonValueForExplorer(value);
                break;
            case "items[0].authority":
            case "authority":
                target["authority"] = JsonValueForExplorer(value);
                break;
            case "signature":
                target["signature"] = JsonValueForExplorer(value);
                break;
            case "nonce":
                target["nonce"] = JsonValueForExplorer(value);
                break;
            case "time_to_live.ms":
                ((JsonObject)target["time_to_live"]!)["ms"] = JsonValueForExplorer(value);
                break;
            case "rejection_reason.encoded":
                ((JsonObject)target["rejection_reason"]!)["encoded"] = JsonValueForExplorer(value);
                break;
            case "items[0].transaction_hash":
            case "transaction_hash":
                target["transaction_hash"] = JsonValueForExplorer(value);
                break;
            case "items[0].box.encoded":
            case "box.encoded":
                ((JsonObject)target["box"]!)["encoded"] = JsonValueForExplorer(value);
                break;
            case "box":
                target["box"] = JsonValueForExplorer(value);
                break;
            case "box.json":
                ((JsonObject)target["box"]!)["json"] = JsonValueForExplorer(value);
                break;
            case "box.json.encoded":
                ((JsonObject)((JsonObject)target["box"]!)["json"]!)["encoded"] = JsonValueForExplorer(value);
                break;
            default:
                throw new ArgumentOutOfRangeException(nameof(field), field, "Unknown explorer response field.");
        }

        return root.ToJsonString();
    }

    private static void RemoveExplorerResponseField(JsonObject root, JsonObject target, string field)
    {
        switch (field)
        {
            case "pagination.page":
                ((JsonObject)root["pagination"]!).Remove("page");
                break;
            case "pagination.per_page":
                ((JsonObject)root["pagination"]!).Remove("per_page");
                break;
            case "pagination":
                root.Remove("pagination");
                break;
            case "items":
                root.Remove("items");
                break;
            case "sampled_at":
                root.Remove("sampled_at");
                break;
            case "items[0].hash":
            case "hash":
                target.Remove("hash");
                break;
            case "items[0].created_at":
            case "created_at":
                target.Remove("created_at");
                break;
            case "items[0].height":
            case "height":
                target.Remove("height");
                break;
            case "items[0].transactions_rejected":
            case "transactions_rejected":
                target.Remove("transactions_rejected");
                break;
            case "items[0].transactions_total":
            case "transactions_total":
                target.Remove("transactions_total");
                break;
            case "items[0].block":
            case "block":
                target.Remove("block");
                break;
            case "items[0].authority":
            case "authority":
                target.Remove("authority");
                break;
            case "items[0].index":
            case "index":
                target.Remove("index");
                break;
            case "items[0].transaction_hash":
            case "transaction_hash":
                target.Remove("transaction_hash");
                break;
            case "items[0].box":
            case "box":
                target.Remove("box");
                break;
            default:
                throw new ArgumentOutOfRangeException(nameof(field), field, "Unknown removable explorer response field.");
        }
    }

