    private static string ContractMetadataHashResponseJson(string operation, string field, string value)
    {
        var codeHash = ContractCodeHashHex;
        var declaredCodeHash = ContractCodeHashHex;
        var abiHash = ContractAbiHashHex;
        var manifestCodeHash = ContractManifestCodeHashLiteral;
        var manifestAbiHash = ContractManifestAbiHashLiteral;
        var codeHashHex = ContractCodeHashHex;
        var abiHashHex = ContractAbiHashHex;
        var actualCodeHash = ContractCodeHashHex;
        var verifiedSourceLanguage = "kotodama";
        var verifiedSourceName = "demo.ko";
        var verifiedSourceSubmittedAt = "2026-03-29T13:00:01Z";
        var verifiedSourceManifestIdHex = VerifiedSourceManifestIdHex;
        var verifiedSourcePayloadDigestHex = VerifiedSourcePayloadDigestHex;

        switch ((operation, field))
        {
            case ("contract-code", "manifest.code_hash"):
                manifestCodeHash = value;
                break;
            case ("contract-code", "manifest.abi_hash"):
                manifestAbiHash = value;
                break;
            case ("contract-instances", "instances[0].code_hash_hex"):
                codeHashHex = value;
                break;
            case ("contract-code-view", "code_hash"):
            case ("explorer-instruction-contract-view", "code_hash"):
                codeHash = value;
                break;
            case ("contract-code-view", "declared_code_hash"):
            case ("explorer-instruction-contract-view", "declared_code_hash"):
                declaredCodeHash = value;
                break;
            case ("contract-code-view", "abi_hash"):
            case ("explorer-instruction-contract-view", "abi_hash"):
                abiHash = value;
                break;
            case ("contract-call", "code_hash_hex"):
            case ("contract-view-success", "code_hash_hex"):
            case ("contract-view-error", "code_hash_hex"):
                codeHashHex = value;
                break;
            case ("contract-call", "abi_hash_hex"):
            case ("contract-view-success", "abi_hash_hex"):
            case ("contract-view-error", "abi_hash_hex"):
            case ("runtime-abi-hash", "abi_hash_hex"):
                abiHashHex = value;
                break;
            case ("verified-source-submit", "code_hash"):
            case ("verified-source-get", "code_hash"):
                codeHash = value;
                break;
            case ("verified-source-submit", "actual_code_hash"):
            case ("verified-source-get", "actual_code_hash"):
                actualCodeHash = value;
                break;
            case ("contract-code-view", "verified_source_ref.language"):
            case ("explorer-instruction-contract-view", "verified_source_ref.language"):
            case ("verified-source-submit", "verified_source_ref.language"):
            case ("verified-source-get", "verified_source_ref.language"):
                verifiedSourceLanguage = value;
                break;
            case ("contract-code-view", "verified_source_ref.source_name"):
            case ("explorer-instruction-contract-view", "verified_source_ref.source_name"):
            case ("verified-source-submit", "verified_source_ref.source_name"):
            case ("verified-source-get", "verified_source_ref.source_name"):
                verifiedSourceName = value;
                break;
            case ("contract-code-view", "verified_source_ref.submitted_at"):
            case ("explorer-instruction-contract-view", "verified_source_ref.submitted_at"):
            case ("verified-source-submit", "verified_source_ref.submitted_at"):
            case ("verified-source-get", "verified_source_ref.submitted_at"):
                verifiedSourceSubmittedAt = value;
                break;
            case ("contract-code-view", "verified_source_ref.manifest_id_hex"):
            case ("explorer-instruction-contract-view", "verified_source_ref.manifest_id_hex"):
            case ("verified-source-submit", "verified_source_ref.manifest_id_hex"):
            case ("verified-source-get", "verified_source_ref.manifest_id_hex"):
                verifiedSourceManifestIdHex = value;
                break;
            case ("contract-code-view", "verified_source_ref.payload_digest_hex"):
            case ("explorer-instruction-contract-view", "verified_source_ref.payload_digest_hex"):
            case ("verified-source-submit", "verified_source_ref.payload_digest_hex"):
            case ("verified-source-get", "verified_source_ref.payload_digest_hex"):
                verifiedSourcePayloadDigestHex = value;
                break;
            default:
                throw new ArgumentOutOfRangeException(nameof(field), field, "Unknown contract metadata hash field.");
        }

        return operation switch
        {
            "contract-code" => new JsonObject
            {
                ["manifest"] = new JsonObject
                {
                    ["code_hash"] = manifestCodeHash,
                    ["abi_hash"] = manifestAbiHash,
                },
            }.ToJsonString(),
            "contract-instances" => new JsonObject
            {
                ["namespace"] = "universal",
                ["instances"] = new JsonArray(new JsonObject
                {
                    ["contract_id"] = "router::dex.universal",
                    ["code_hash_hex"] = codeHashHex,
                }),
                ["total"] = 1,
                ["offset"] = 0,
                ["limit"] = 1,
            }.ToJsonString(),
            "contract-code-view" or "explorer-instruction-contract-view" =>
                ContractCodeViewResponseJson(
                    codeHash,
                    declaredCodeHash,
                    abiHash,
                    verifiedSourceLanguage,
                    verifiedSourceName,
                    verifiedSourceSubmittedAt,
                    verifiedSourceManifestIdHex,
                    verifiedSourcePayloadDigestHex),
            "contract-call" => ContractCallResponseJson(codeHashHex, abiHashHex),
            "contract-view-success" => ContractViewSuccessResponseJson(codeHashHex, abiHashHex),
            "contract-view-error" => ContractViewErrorResponseJson(codeHashHex, abiHashHex),
            "verified-source-submit" or "verified-source-get" => ContractVerifiedSourceJobResponseJson(
                codeHash,
                actualCodeHash,
                verifiedSourceLanguage,
                verifiedSourceName,
                verifiedSourceSubmittedAt,
                verifiedSourceManifestIdHex,
                verifiedSourcePayloadDigestHex),
            "runtime-abi-hash" => new JsonObject
            {
                ["policy"] = "V1",
                ["abi_hash_hex"] = abiHashHex,
            }.ToJsonString(),
            _ => throw new ArgumentOutOfRangeException(nameof(operation), operation, "Unknown contract metadata hash operation."),
        };
    }

    private static string ContractCodeRecordRawResponseJson(string field, object? value)
    {
        var response = new JsonObject
        {
            ["manifest"] = new JsonObject
            {
                ["code_hash"] = ContractCodeHashHex,
                ["abi_hash"] = ContractAbiHashHex,
            },
        };

        if (field == "manifest")
        {
            response["manifest"] = JsonValueForContractCodeView(value);
        }
        else if (field.StartsWith("manifest.", StringComparison.Ordinal))
        {
            var manifest = (JsonObject)response["manifest"]!;
            manifest[field["manifest.".Length..]] = JsonValueForContractCodeView(value);
        }
        else
        {
            throw new ArgumentOutOfRangeException(nameof(field), field, "Unknown contract code record field.");
        }

        return response.ToJsonString();
    }

