            case "vm_diagnostic.source_path":
            case "vm_diagnostic.current_function":
            case "vm_diagnostic.gas_limit":
            case "vm_diagnostic.gas_remaining":
            case "vm_diagnostic.gas_used":
            case "vm_diagnostic.max_cycles":
            case "vm_diagnostic.cycles":
            case "vm_diagnostic.stack_limit_bytes":
