    private static void MutateProtectedRequestState(HttpRequestMessage request, string mutation)
    {
        switch (mutation)
        {
            case "method":
                request.Method = HttpMethod.Post;
                break;
            case "uri":
                request.RequestUri = new Uri("https://evil.example/v1/query");
                break;
            case "content":
                request.Content = new StringContent("{\"ok\":false}");
                break;
            case "authorization":
                request.Headers.Authorization = new System.Net.Http.Headers.AuthenticationHeaderValue("Bearer", "other-token");
                break;
            case "accept":
                request.Headers.Accept.Clear();
                break;
            case "signature":
                request.Headers.Remove("X-Iroha-Signature");
                break;
            default:
                throw new ArgumentOutOfRangeException(nameof(mutation), mutation, "Unknown protected request mutation.");
        }
    }

